// foxy-render.js — Foxy's page renderer. Written for Foxy, in this repo.
//
// It replaces a 1,858-line runtime generated by a design tool, which came with
// no source and no version. That runtime did far more than Foxy uses —
// streaming placeholders, component imports, iframe page bundles, slide decks,
// an editor bridge — and most of it was dormant surface in the page that holds
// the wallet. This does only what Foxy's template and app class use, and
// refuses anything else when the page starts, loudly, rather than half-doing it.
//
// What it does, and nothing more:
//   - loads React and ReactDOM from the blobs the page loader unpacked;
//   - compiles the <x-dc> template: <sc-if value>, <sc-for list as>, {{ name }}
//     and {{ a.b.c }} in text and attributes, event and camel-case attributes,
//     style strings, style-active / style-hover rules, <helmet> styles;
//   - runs the app class (from the loader's factory, never from text) in a
//     host that merges state synchronously, as the old runtime did.
//
// tests/render-parity.js renders every screen with this and with the old
// runtime (kept in tests/reference only for that) and compares the DOM.
'use strict';
(() => {
  const REACT_URL = 'https://unpkg.com/react@18.3.1/umd/react.production.min.js';
  const REACT_DOM_URL = 'https://unpkg.com/react-dom@18.3.1/umd/react-dom.production.min.js';
  const FULL_PAGE_CSS = 'html,body{height:100%;margin:0}#dc-root,#dc-root>.sc-host{height:100%}';
  const ERROR_CSS = '.sc-host.sc-has-error{position:relative}'
    + '.sc-logic-error{position:absolute;top:8px;left:8px;z-index:2147483647;max-width:60ch;'
    + 'padding:6px 10px;background:#b00020;color:#fff;font:12px/1.4 ui-monospace,monospace;'
    + 'border-radius:4px;white-space:pre-wrap;pointer-events:none}';

  let React = null;
  let ReactDOM = null;
  const h = (...args) => React.createElement(...args);
  const message = (e) => (e instanceof Error && e.message ? e.message : String(e));

  /* ---- expressions --------------------------------------------------------
   * A name, a dotted path (a.b, a.0), true or false. Nothing is evaluated as
   * code; anything else in the template stops the page at compile time. */
  const PATH_RE = /^[A-Za-z_$][A-Za-z0-9_$]*(?:\.(?:[A-Za-z_$][A-Za-z0-9_$]*|\d+))*$/;

  function compileExpr(source) {
    const expr = String(source).trim();
    if (expr === 'true') return () => true;
    if (expr === 'false') return () => false;
    if (!PATH_RE.test(expr)) throw new Error('foxy-render: unsupported expression {{ ' + expr + ' }}');
    const parts = expr.split('.');
    return (vals) => {
      let cur = vals;
      for (const p of parts) {
        if (cur == null) return undefined;
        cur = cur[p];
      }
      return cur;
    };
  }

  // a whole-value binding keeps its type (a function, a ref, a boolean); a mixed one is text
  function compileAttr(raw) {
    const whole = raw.match(/^\s*\{\{([\s\S]+?)\}\}\s*$/);
    if (whole) return compileExpr(whole[1]);
    if (raw.includes('{{')) {
      const parts = raw.split(/\{\{([\s\S]+?)\}\}/g).map((s, i) => (i & 1 ? compileExpr(s) : s));
      return (vals) => parts.map((p) => (typeof p === 'function' ? (p(vals) ?? '') : p)).join('');
    }
    return () => raw;
  }

  /* ---- template source -----------------------------------------------------
   * The HTML parser lower-cases attribute names, so camelCase ones are carried
   * through as sc-camel-kebab-case and turned back; <helmet> would be eaten by
   * the parser, so it travels as <sc-helmet>. */
  const CAMEL_PREFIX = 'sc-camel-';
  const CAMEL_ATTR_RE = /(\s)([a-z]+[A-Z][A-Za-z0-9]*)(\s*=)/g;
  const UNSUPPORTED_TAG_RE = /<(x-import|dc-import|sc-else|deck-stage|select|table|tbody|thead|tfoot|tr|td|th|caption)[\s>/]/i;

  function encode(html) {
    const bad = UNSUPPORTED_TAG_RE.exec(html);
    if (bad) throw new Error('foxy-render: the template uses <' + bad[1] + '>, which this renderer does not support');
    return html
      .replace(/<helmet(\s|>)/gi, '<sc-helmet$1')
      .replace(/<\/helmet\s*>/gi, '</sc-helmet>')
      .replace(CAMEL_ATTR_RE, (_, sp, name, eq) =>
        sp + CAMEL_PREFIX + name.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase()) + eq);
  }

  const kebabToCamel = (s) => s.replace(/-([a-z])/g, (_, c) => c.toUpperCase());

  function cssToObject(css) {
    const out = {};
    for (const decl of css.split(';')) {
      const i = decl.indexOf(':');
      if (i < 0) continue;
      const prop = decl.slice(0, i).trim();
      out[prop.startsWith('--') ? prop : kebabToCamel(prop)] = decl.slice(i + 1).trim();
    }
    return out;
  }

  /* ---- style-active / style-hover: one class per rule, !important ---------- */
  function scanUnquotedUrl(css, i) {
    if ((css[i] !== 'u' && css[i] !== 'U') || css.slice(i, i + 4).toLowerCase() !== 'url('
        || /[a-z0-9_-]/i.test(css[i - 1] ?? '')) return -1;
    let j = i + 4;
    while (j < css.length && /\s/.test(css[j])) j++;
    if (css[j] === '"' || css[j] === "'") return -1;
    while (j < css.length && css[j] !== ')') {
      if (css[j] === '\\') j++;
      j++;
    }
    return j < css.length ? j + 1 : css.length;
  }

  function stripComments(css) {
    let out = '';
    let quote = '';
    for (let i = 0; i < css.length; i++) {
      const c = css[i];
      if (quote) {
        if (c === '\\') { out += c + (css[i + 1] ?? ''); i++; continue; }
        if (c === quote) quote = '';
        out += c;
      } else if (c === "'" || c === '"') {
        quote = c;
        out += c;
      } else if (c === '/' && css[i + 1] === '*') {
        const end = css.indexOf('*/', i + 2);
        i = end === -1 ? css.length : end + 1;
        out += ' ';
      } else {
        const end = scanUnquotedUrl(css, i);
        if (end === -1) out += c;
        else { out += css.slice(i, end); i = end - 1; }
      }
    }
    return out;
  }

  function importantify(css) {
    css = stripComments(css);
    const decls = [];
    let start = 0;
    let depth = 0;
    let quote = '';
    for (let i = 0; i < css.length; i++) {
      const c = css[i];
      if (quote) {
        if (c === '\\') i++;
        else if (c === quote) quote = '';
      } else if (c === "'" || c === '"') quote = c;
      else if (c === '(') depth++;
      else if (c === ')') depth = Math.max(0, depth - 1);
      else if (c === ';' && depth === 0) { decls.push(css.slice(start, i)); start = i + 1; }
      else {
        const end = scanUnquotedUrl(css, i);
        if (end !== -1) i = end - 1;
      }
    }
    decls.push(css.slice(start));
    return decls.map((d) => d.trim()).filter(Boolean)
      .map((d) => (/!\s*important$/i.test(d) ? d : d + ' !important')).join(';');
  }

  // prefix: 'scp' for a style fixed in the template, 'scd' for one with {{ bindings }}
  const pseudoClass = (() => {
    let sheet = null;
    const cache = new Map();
    let n = 0;
    return (pseudo, css, prefix) => {
      const k = pseudo + '|' + css;
      if (cache.has(k)) return cache.get(k);
      if (!sheet) {
        const el = document.createElement('style');
        document.head.appendChild(el);
        sheet = el.sheet;
      }
      const cls = (prefix || 'scp') + (n++).toString(36);
      const isElement = pseudo === 'before' || pseudo === 'after';
      const selector = '.' + cls + (isElement ? '::' : ':') + pseudo;
      sheet.insertRule(selector + '{' + (isElement ? css : importantify(css)) + '}', sheet.cssRules.length);
      cache.set(k, cls);
      return cls;
    };
  })();

  /* ---- compile --------------------------------------------------------------
   * Each node becomes a builder (vals, key) => React node. Children are keyed
   * by position, and an sc-if that is off still holds its slot, so a field
   * keeps its focus while the screen around it re-renders. */
  const INLINE_TAGS = 'a abbr b bdi bdo br cite code del dfn em i ins kbd mark q s samp small span strike strong sub sup u var wbr'.split(' ');
  const NOT_INLINE = ':not(' + INLINE_TAGS.join(',') + ')';
  const NEVER_CONTENT_KEYED = new Set('script style textarea option title select canvas iframe video audio'.split(' '));
  const warned = new Set();
  function warnOnce(what) {
    if (warned.has(what)) return;
    warned.add(what);
    console.warn('[foxy-render] ' + what);
  }

  // an element whose content is inline text only is keyed by that content as well
  function contentKey(el) {
    const clone = el.cloneNode(true);
    for (const d of clone.querySelectorAll('*')) {
      while (d.attributes.length) d.removeAttribute(d.attributes[0].name);
    }
    const s = clone.innerHTML;
    let hash = 5381;
    for (let i = 0; i < s.length; i++) hash = ((hash << 5) + hash + s.charCodeAt(i)) | 0;
    return s.length + '.' + (hash >>> 0).toString(36);
  }

  function collectProps(el) {
    const getters = [];
    const pseudo = [];
    const boundPseudo = [];
    for (const { name, value } of [...el.attributes]) {
      let key = name;
      if (key.startsWith(CAMEL_PREFIX)) key = kebabToCamel(key.slice(CAMEL_PREFIX.length));
      if (key.startsWith('style-')) {
        /* A pressed or hover style with a binding is filled in at render, one
         * class per distinct value. The design-tool runtime compiled these from
         * the raw text, so "box-shadow:{{ emailActSh }}" was invalid CSS and the
         * pressed shadow silently never showed. */
        if (value.includes('{{')) boundPseudo.push([key.slice(6), compileAttr(value)]);
        else pseudo.push(pseudoClass(key.slice(6), value));
        continue;
      }
      if (key === 'class') key = 'className';
      else if (key === 'for') key = 'htmlFor';
      else if (key.startsWith('on')) key = 'on' + key[2].toUpperCase() + key.slice(3);
      getters.push([key, compileAttr(value)]);
    }
    return { getters, pseudo, boundPseudo };
  }

  function walkChildren(node) {
    return [...node.childNodes].map(walk).filter((b) => b != null);
  }

  function walk(node) {
    if (node.nodeType === Node.TEXT_NODE) return walkText(node);
    if (node.nodeType !== Node.ELEMENT_NODE) return null;
    const tag = node.localName;
    if (tag === 'sc-for') return walkFor(node);
    if (tag === 'sc-if') return walkIf(node);
    if (tag === 'sc-helmet') return walkHelmet(node);
    return walkElement(node);
  }

  function walkText(node) {
    const text = node.nodeValue ?? '';
    if (!text.includes('{{')) {
      // newline-only runs between tags are layout of the source, not content
      if (!text.trim() && !text.includes(' ')) return null;
      return () => text;
    }
    const parts = text.split(/\{\{([\s\S]+?)\}\}/g).map((s, i) => (i & 1 ? [s.trim(), compileExpr(s)] : s));
    return (vals, key) => h(React.Fragment, { key }, ...parts.map((p, i) => {
      if (typeof p === 'string') return p;
      const v = p[1](vals);
      if (v === undefined) { warnOnce('{{ ' + p[0] + ' }} never resolved — rendered as empty'); return null; }
      if (React.isValidElement(v) || Array.isArray(v)) return h(React.Fragment, { key: i }, v);
      if (v === null || typeof v === 'boolean') return null;
      return h('span', { key: i, className: 'sc-interp' }, String(v));
    }));
  }

  function walkFor(el) {
    /* `list`, and nothing else. An sc-for spelled any other way used to
     * compile to the empty string, which reads as an empty list: the loop drew
     * nothing, for ever, and said so only in a console warning nobody was
     * watching. A whole screen shipped blank that way (the ERRORS and LOGS
     * list, written `each=`). This renderer refuses what it does
     * not understand everywhere else; here it did not. */
    const source = el.getAttribute('list') || '';
    if (!source) {
      throw new Error('[foxy-render] <sc-for> needs list="{{ … }}"'
        + (el.getAttribute('each') ? ' — this one says each="' + el.getAttribute('each') + '"' : ''));
    }
    const getList = compileAttr(source);
    const as = el.getAttribute('as') || 'item';
    const kids = walkChildren(el);
    return (vals, key) => {
      let list = getList(vals);
      if (!Array.isArray(list)) {
        if (list != null) warnOnce('sc-for list="' + source + '" is not an array (' + typeof list + ')');
        list = [];
      }
      return h(React.Fragment, { key }, list.map((item, i) => {
        const sub = { ...vals, [as]: item, $index: i };
        return h(React.Fragment, { key: i }, kids.map((b, j) => b(sub, j)));
      }));
    };
  }

  function walkIf(el) {
    const getValue = compileAttr(el.getAttribute('value') || '');
    const kids = walkChildren(el);
    return (vals, key) => (getValue(vals) ? h(React.Fragment, { key }, kids.map((b, j) => b(vals, j))) : null);
  }

  function walkElement(el) {
    const tag = el.localName;
    const inlineOnly = el.childNodes.length > 0 && !NEVER_CONTENT_KEYED.has(tag) && el.querySelector(NOT_INLINE) === null;
    const keySuffix = inlineOnly ? '|' + contentKey(el) : '';
    const { getters, pseudo, boundPseudo } = collectProps(el);
    const kids = walkChildren(el);
    return (vals, key) => {
      const props = { key: key + keySuffix };
      for (const [k, get] of getters) {
        let v = get(vals);
        if (k === 'style' && typeof v === 'string') v = cssToObject(v);
        if ((k === 'value' || k === 'checked') && v === undefined) v = k === 'checked' ? false : '';
        props[k] = v;
      }
      const classes = boundPseudo.length
        ? pseudo.concat(boundPseudo.map(([p, get]) => pseudoClass(p, get(vals), 'scd')))
        : pseudo;
      if (classes.length) props.className = [props.className, ...classes].filter(Boolean).join(' ');
      return h(tag, props, ...kids.map((b, j) => b(vals, j)));
    };
  }

  /* <helmet>: meta tags into <head> once; style blocks kept live there. It
   * renders nothing in place. A script in it is refused — the page policy
   * would refuse it anyway. */
  function walkHelmet(node) {
    const children = [...node.children];
    const mounted = new Set();
    const live = new Map();
    return () => {
      children.forEach((child, i) => {
        const tag = child.tagName;
        if (tag === 'SCRIPT') { warnOnce('a <script> in <helmet> is not run'); return; }
        if (tag === 'META' || tag === 'LINK') {
          const k = tag + '|' + (child.getAttribute('href') || child.getAttribute('src') || child.outerHTML);
          if (!mounted.has(k)) { mounted.add(k); document.head.appendChild(child.cloneNode(true)); }
          return;
        }
        let el = live.get(i);
        if (!el || el.tagName !== tag) {
          if (el) el.remove();
          el = document.createElement(tag.toLowerCase());
          live.set(i, el);
          document.head.appendChild(el);
        }
        for (const { name, value } of [...child.attributes]) {
          if (el.getAttribute(name) !== value) el.setAttribute(name, value);
        }
        if (el.textContent !== child.textContent) el.textContent = child.textContent;
      });
      return null;
    };
  }

  function compileTemplate(html) {
    const tpl = document.createElement('template');
    tpl.innerHTML = encode(html);
    const builders = walkChildren(tpl.content);
    return (vals) => builders.map((b, i) => b(vals || {}, i));
  }

  /* ---- the app ----------------------------------------------------------- */
  class DCLogic {
    constructor(props) {
      this.props = props || {};
      this.state = {};
      this.__host = undefined;
    }
    setState(update, cb) { if (this.__host) this.__host.__setLogicState(update, cb); }
    forceUpdate() { if (this.__host) this.__host.forceUpdate(); }
    componentDidMount() {}
    componentDidUpdate() {}
    componentWillUnmount() {}
    renderVals() { return {}; }
  }

  // The app's class, from the factory the page loader built out of its script —
  // never compiled from text here. (The name is what smoke check 16 looks for.)
  function evalDcLogic() {
    const factory = window.__foxyComponentFactory;
    if (typeof factory !== 'function') throw new Error('[foxy] the app script did not load');
    return factory(DCLogic, DCLogic, React);
  }

  function makeHost(Logic, render, name) {
    return class FoxyHost extends React.Component {
      constructor(props) {
        super(props);
        this.state = { v: 0, err: null };
        this.startError = null;
        try {
          this.logic = new Logic(props);
        } catch (e) {
          console.error(e);
          this.startError = name + ': ' + message(e);
          this.logic = new DCLogic(props);
        }
        this.logic.__host = this;
        this.renderedState = this.logic.state;
        this.previousState = this.logic.state;
      }

      static getDerivedStateFromError(e) { return { err: message(e) }; }

      componentDidCatch(e, info) {
        console.error('[foxy-render] render error:', e, (info && info.componentStack) || '');
      }

      // merged at once, as the app expects: a setState followed by a read sees the new state
      __setLogicState(update, cb) {
        const prev = this.logic.state;
        const patch = typeof update === 'function' ? update(prev) : update;
        this.logic.state = { ...prev, ...patch };
        this.setState((s) => ({ v: s.v + 1 }), cb);
      }

      componentDidMount() {
        try { this.logic.componentDidMount(); } catch (e) { console.error(e); }
      }

      // prevState as well as prevProps: the old runtime passed only the props, so
      // the app's checks against the previous screen never ran
      componentDidUpdate(prevProps) {
        this.logic.props = this.props;
        try { this.logic.componentDidUpdate(prevProps, this.previousState); } catch (e) { console.error(e); }
      }

      componentWillUnmount() {
        try { this.logic.componentWillUnmount(); } catch (e) { console.error(e); }
      }

      render() {
        const base = { className: 'sc-host', 'data-sc-name': name };
        if (this.state.err) {
          return h('div', { ...base, className: 'sc-host sc-has-error' },
            h('div', { className: 'sc-logic-error' }, name + ': ' + this.state.err));
        }
        this.previousState = this.renderedState;
        this.renderedState = this.logic.state;
        this.logic.props = this.props;
        let vals = this.props;
        let err = this.startError;
        try {
          vals = { ...this.props, ...(this.logic.renderVals() || {}) };
        } catch (e) {
          console.error(e);
          err = name + '.renderVals(): ' + message(e);
        }
        return h('div', { ...base, className: 'sc-host' + (err ? ' sc-has-error' : '') },
          err && h('div', { className: 'sc-logic-error' }, err),
          render(vals));
      }
    };
  }

  // defaults declared on the app script's data-props
  function propDefaults(raw) {
    const out = {};
    let parsed = null;
    try { parsed = raw ? JSON.parse(raw) : null; } catch (e) { return out; }
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return out;
    for (const k of Object.keys(parsed)) {
      if (k[0] === '$') continue;
      const d = parsed[k] && parsed[k].default;
      if (d !== undefined) out[k] = d;
    }
    return out;
  }

  function boot() {
    const dc = document.querySelector('x-dc');
    if (!dc) return;
    const scriptEl = document.querySelector('script[data-dc-script]');
    const render = compileTemplate(dc.innerHTML);
    let Logic = DCLogic;
    try {
      const C = evalDcLogic();
      if (typeof C === 'function') Logic = C;
      else console.error('[foxy-render] the app script did not define Component');
    } catch (e) {
      console.error('[foxy-render] the app class failed to load — the template renders with props only', e);
    }
    const name = (location.pathname.split('/').pop() || 'Root').replace(/\.html?$/, '') || 'Root';
    const root = document.createElement('div');
    root.id = 'dc-root';
    dc.replaceWith(root);
    const css = document.createElement('style');
    css.textContent = FULL_PAGE_CSS + ERROR_CSS;
    document.head.appendChild(css);
    const Host = makeHost(Logic, render, name);
    ReactDOM.createRoot(root).render(h(Host, propDefaults(scriptEl && scriptEl.getAttribute('data-props'))));
  }

  /* ---- React, from the page's own blobs only -------------------------------- */
  function loadScript(src) {
    return new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = src;
      s.async = false;
      s.onload = () => resolve();
      s.onerror = () => reject(new Error('failed to load ' + src));
      document.head.appendChild(s);
    });
  }

  function loadReact() {
    if (window.React && window.ReactDOM) return Promise.resolve();
    const res = window.__resources || {};
    const react = typeof res[REACT_URL] === 'string' && res[REACT_URL].startsWith('blob:') ? res[REACT_URL] : null;
    const reactDom = typeof res[REACT_DOM_URL] === 'string' && res[REACT_DOM_URL].startsWith('blob:') ? res[REACT_DOM_URL] : null;
    if (!react || !reactDom) return Promise.reject(new Error('[foxy] React is not embedded in this page'));
    return Promise.all([loadScript(react), loadScript(reactDom)]).then(() => undefined);
  }

  const hide = document.createElement('style');
  hide.textContent = 'x-dc{display:none!important}';
  document.head.appendChild(hide);

  loadReact().then(() => {
    React = window.React;
    ReactDOM = window.ReactDOM;
    if (document.readyState !== 'loading') boot();
    else document.addEventListener('DOMContentLoaded', boot);
  }).catch((e) => {
    console.error('[foxy-render] could not start:', e);
  });
})();
